def _picture(slug: str, alt: str) -> str:
    day_path = OUTPUT_PATHS[slug].as_posix()
    night_path = DARK_OUTPUT_PATHS[slug].as_posix()
    return f'''<picture>
  <source media="(prefers-color-scheme: dark)" srcset="{night_path}">
  <img src="{day_path}" alt="{alt}">
</picture>'''


